fun Interpolation_Search(@init<table> collection, target):
    low = 0
    high = length(collection) - 1

    while (low <= high and target >= collection[low] and target <= collection[high]):
        if (low == high):
            @mark<low, highlight, yellow> val = collection[low]
            if (val == target):
                @mark<low, highlight, green> return low
            end if
            @log<warn, "Not found"> return -1
        end if

        // Estimate the position using interpolation formula
        numerator = (target - collection[low]) * (high - low)
        denominator = collection[high] - collection[low]
        pos = low + floor(numerator / denominator)

        // Get value at the estimated position
        @mark<pos, outline, yellow> val = collection[pos]

        if (val == target):
            @mark<pos, highlight, green> return pos
        end if

        if (val < target):
            @mark<low, outline, yellow> low = pos + 1
        end if

        if (val > target):
            @mark<high, outline, yellow> high = pos - 1
        end if
    end while

    @log<warn, "Not found"> return -1
end fun

